-- Phase 2 (part 2d): Roof Deck Labor - Underlayment Times + Tearoff Times tabs.
-- Idempotent. RLS: authenticated read, admin-only write.

create table if not exists public.rdl_labor_tables (
  id text primary key,
  title text not null,
  data jsonb not null default '{}'::jsonb,
  sort integer not null default 0
);
alter table public.rdl_labor_tables enable row level security;
revoke all on public.rdl_labor_tables from anon;
drop policy if exists rdl_labor_tables_read on public.rdl_labor_tables;
create policy rdl_labor_tables_read on public.rdl_labor_tables for select to authenticated using (true);
drop policy if exists rdl_labor_tables_write on public.rdl_labor_tables;
create policy rdl_labor_tables_write on public.rdl_labor_tables for all to authenticated using (public.is_admin()) with check (public.is_admin());
insert into public.rdl_labor_tables (id, title, data, sort)
select * from (values
  ('underlayment_layout_mechanical','Underlayment Times — Layout & Mechanical','{"description": "Underlayment Times > Layout & Mechanical sub-tab. EDITABLE inputs only. Per app header: ''Labor = Layout Time + (Time for One Fastener by Deck Type) * # Fasteners in 2500 SqFt''. Editable green cells are (a) the single shared per-deck fastening-time row in Minutes/Fastener, and (b) each product''s Layout Time in Hours/2500SqFt. The per-product x per-deck brown cells are COMPUTED LABOR PREVIEW (not editable) and are excluded per the capture rule; see excluded_preview_note.", "deck_columns": ["Wood", "Steel", "Metal Retrofit", "Concrete", "Gypsum", "LWC / Concrete", "LWC / Steel", "LWC / Other", "Tectum", "Purlin Fastened"], "fastening_times_min_per_fastener_by_deck": {"Wood": 0.342, "Steel": 0.462, "Metal Retrofit": 0.462, "Concrete": 2.185, "Gypsum": 1.3, "LWC / Concrete": 0.858, "LWC / Steel": 2.185, "LWC / Other": 1.3, "Tectum": 0.858, "Purlin Fastened": 0.462}, "rows": [{"underlayment": "1/4\" Dens Deck", "layout_hours_per_2500sqft": 23.419}, {"underlayment": "1/2\" HD ISO 4''x 4''", "layout_hours_per_2500sqft": 8.5525}, {"underlayment": "1/2\" ISO", "layout_hours_per_2500sqft": 7.775}, {"underlayment": "1/2\" Rigid 4''x 4''", "layout_hours_per_2500sqft": 8.5525}, {"underlayment": "1\" ISO", "layout_hours_per_2500sqft": 8.775}, {"underlayment": "1\" ISO 4''x 4''", "layout_hours_per_2500sqft": 9.6525}, {"underlayment": "1\" Rigid", "layout_hours_per_2500sqft": 8.775}, {"underlayment": "1\" Rigid 4''x 4''", "layout_hours_per_2500sqft": 9.6525}, {"underlayment": "1/2\" DensDeck P...", "layout_hours_per_2500sqft": 20, "name_truncated": true, "layout_pale_yellow": true}, {"underlayment": "1/2\" Securock G...", "layout_hours_per_2500sqft": 20, "name_truncated": true, "layout_pale_yellow": true}, {"underlayment": "1/4\" DensDeck P...", "layout_hours_per_2500sqft": 18, "name_truncated": true, "layout_pale_yellow": true}, {"underlayment": "1/4\" Securock G...", "layout_hours_p